import { api } from "encore.dev";
import { createSchema, createYoga } from "graphql-yoga";

const typeDefs = `
  type Query {
    """Returns a hello message. If no name is provided, returns 'Hello, World!'"""
    hello(name: String): String!
  }
`;

const resolvers = {
  Query: {
    hello: (_parent: unknown, args: { name?: string | null }) => {
      const name = args.name ?? "World";
      return `Hello, ${name}!`;
    },
  },
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  graphqlEndpoint: "/graphql",
  landingPage: false,
  graphiql: false,
});

export const graphql = api.raw(
  { expose: true, method: "*", path: "/graphql" },
  async (ctx) => {
    const request = ctx.request;
    const url = new URL(request.url);
    const headers: Record<string, string> = {};
    request.headers.forEach((value, key) => {
      headers[key] = value;
    });

    const method = request.method;
    let body: BodyInit | undefined;
    const contentType = request.headers.get("content-type") ?? "";
    if (method !== "GET" && method !== "HEAD" && request.body) {
      const cloned = request.clone();
      if (contentType.includes("application/json")) {
        const text = await cloned.text();
        body = text;
      } else {
        body = await cloned.arrayBuffer().then((buf) => new Uint8Array(buf));
      }
    }

    const yogaRequest = new Request(request.url, {
      method,
      headers,
      body,
    } as RequestInit);

    const response = await yoga.handle(yogaRequest, {});

    const responseHeaders: Record<string, string> = {};
    response.headers.forEach((value, key) => {
      responseHeaders[key] = value;
    });

    const responseBody = await response.text();
    return new Response(responseBody, {
      status: response.status,
      headers: responseHeaders,
    });
  }
);
EOF
